const { accessSync, constants } = await import('node:fs');
const input_path = process.env.INPUT_PATH;
const output_path = process.env.OUTPUT_PATH;
if (!input_path) { throw new Error('Missing input_path'); }
if (!output_path) { throw new Error('Missing output_path'); }
try { accessSync(input_path, constants.R_OK); } catch { throw new Error('Input file not accessible'); }
globalThis.inputPath = input_path;
globalThis.outputPath = output_path;

const { execSync } = await import('node:child_process');
const input = globalThis.inputPath;
const output = globalThis.outputPath;
try { execSync(`convert ${input} ${output}`); } catch (e) { throw new Error('ImageMagick conversion failed: ' + e.message); }
globalThis.resultPath = output;
